/**
 * Cloudflare Worker entry. Wraps the OpenNext-generated Next.js handler and
 * adds the cron (`scheduled`) handler that keeps market data fresh.
 */
// Generated by `opennextjs-cloudflare build`; may not exist before the first build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { runScheduled } from "./lib/ingest/run";

export default {
  fetch: handler.fetch,
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runScheduled(env, controller.scheduledTime));
  },
} satisfies ExportedHandler<CloudflareEnv>;

